INSERT INTO `recipes` (`id`, `category_id`, `name`, `ingredients`, `instructions`, `created_at`) VALUES
(1, 1, 'Trà sữa trân châu đường đen', 'Hồng trà: 100ml, Bột béo: 30g, Trân châu đường đen: 50g, Đường nước: 20ml', '1. Ủ hồng trà. 2. Hòa bột béo và đường. 3. Thêm trân châu đường đen vào ly và rót trà sữa.', '2026-11-01 01:23:14'),
(2, 1, 'Trà sữa Olong', 'Trà Oolong: 120ml, Bột sữa: 35g, Sữa đặc: 15ml', '1. Ủ trà Oolong 10 phút. 2. Khuấy đều với bột sữa và sữa đặc. 3. Thêm đá và thưởng thức.', '2026-11-01 01:23:14'),
(3, 2, 'Trà đào cam sả', 'Trà đen: 100ml, Si rô đào: 20ml, Sả tươi: 2 cây, Đào miếng: 2 miếng', '1. Đập dập sả đun với nước. 2. Pha trà với nước sả và si rô đào. 3. Trang trí bằng đào miếng.', '2026-11-01 01:23:14'),
(9, 1, 'Trà sữa Trân châu Đường đen', '100ml Hồng trà, 30ml Sữa đặc, 20ml Bột béo, 30g Trân châu đen, 20ml Sirup đường đen.', '1. Ủ hồng trà lấy nước cốt và hòa tan sữa đặc, bột béo.\n2. Đun trân châu với đường đen cho thấm.\n3. Rót đường đen quanh thành ly, cho đá, đổ trà sữa vào và thêm trân châu lên trên.', '2026-11-01 12:05:56'),
(10, 1, 'Trà sữa Ô Long nướng', '100ml Trà Ô long, 30ml Sữa đặc, 20ml Bột béo, 20ml Nước đường.', '1. Ủ trà Ô long để lấy nước cốt đậm vị.\n2. Hòa đều nước cốt trà với sữa đặc, bột béo và nước đường.\n3. Thêm đá viên, khuấy đều và thưởng thức.', '2026-11-01 12:05:56'),
(11, 1, 'Trà sữa Khoai môn', '100ml Lục trà, 30g Bột khoai môn nguyên chất, 25ml Sữa đặc, 20ml Nước đường.', '1. Pha ấm nước cốt lục trà.\n2. Hòa tan bột khoai môn với nước trà cho thật mịn.\n3. Thêm sữa đặc, nước đường và đá, lắc đều trong bình shaker rồi đổ ra ly.', '2026-11-01 12:05:56'),
(12, 3, 'Hồng trà Kem trứng nướng', '120ml Hồng trà, 25ml Nước đường, Lớp kem trứng béo ngậy, Bột quế hoặc đường cát.', '1. Ủ hồng trà và pha với nước đường theo khẩu vị.\r\n2. Đổ một lớp kem trứng dày lên trên bề mặt.\r\n3. Rắc một ít đường lên mặt kem rồi dùng bình khò lửa khò nhẹ cho lớp đường chuyển màu caramel thơm phức.', '2026-11-01 12:05:56'),
(13, 2, 'Lục trà Vải hoa hồng', '120ml Lục trà nhài, 30ml Sirup vải, 10ml Sirup hoa hồng, 3 quả vải ngâm.', '1. Ủ lục trà nhài rồi để nguội.\n2. Trộn đều lục trà với sirup vải và sirup hoa hồng.\n3. Cho đá viên và xếp vải ngâm lên trên trang trí.', '2026-11-01 12:05:56'),
(14, 1, 'Trà sữa Matcha đậu đỏ', '100ml Lục trà, 25g Bột matcha Nhật, 30ml Sữa đặc, 20ml Nước đường, 40g Đậu đỏ nấu nhừ.', '1. Pha bột matcha với nước ấm cho tan đều không bị vón cục.\n2. Trộn đều với lục trà, sữa đặc và nước đường.\n3. Cho đá viên vào ly, rót trà sữa matcha và múc đậu đỏ lên trên bề mặt để thưởng thức.', '2026-11-01 12:06:39'),
(15, 1, 'Trà sữa Socola hạt phỉ', '100ml Hồng trà, 20g Bột cacao nguyên chất, 15ml Sirup hạt phỉ (Hazelnut), 30ml Sữa đặc.', '1. Hòa tan bột cacao và sữa đặc với hồng trà nóng.\n2. Thêm sirup hạt phỉ để tạo mùi thơm béo đặc trưng.\n3. Khuấy đều với đá viên và thưởng thức.', '2026-11-01 12:06:39'),
(16, 1, 'Trà sữa Sương sáo hạt é', '100ml Trà đen, 30ml Sữa đặc, 20ml Nước đường, 50g Thạch sương sáo cắt khối, 1 muỗng hạt é ngâm nở.', '1. Pha trà đen với sữa đặc và nước đường thành hỗn hợp trà sữa.\n2. Cho thạch sương sáo và hạt é đã ngâm nở vào đáy ly.\n3. Rót trà sữa vào và thêm đá viên.', '2026-11-01 12:06:39'),
(17, 1, 'Trà sữa Trân châu Đường đen', '- 150ml Hồng trà đặc\r\n- 30ml Sữa tươi không đường\r\n- 20ml Sốt đường đen\r\n- Trân châu đen ngâm đường đen', '1. Tráng ly bằng sốt đường đen.\r\n2. Pha hồng trà với sữa tươi.\r\n3. Thêm đá và trân châu đường đen lên trên.', '2026-11-01 12:06:39'),
(18, 3, 'Trà sữa Ô Long kem cheese (Milk Foam)', '- 150ml Cốt trà ô long\n- 30ml Kem cheese béo mịn\n- 20ml Sữa tươi\n- Một chút muối hồng', '1. Ủ trà ô long và pha cùng một ít đường.\n2. Đánh phần kem cheese với sữa tươi và muối hồng cho sánh đặc.\n3. Rót lớp kem cheese phủ đầy lên mặt ly trà ô long.', '2026-11-01 12:36:04'),
(19, 1, 'Hồng trà sữa trân châu hoàng kim', '- 150ml Hồng trà đặc\n- 30g Bột béo\n- 20ml Sữa đặc\n- Trân châu hoàng kim dai giòn', '1. Pha hồng trà ấm với bột béo và sữa đặc.\n2. Thêm đá viên và trân châu hoàng kim vào thưởng thức.', '2026-11-01 12:36:04'),
(20, 3, 'Lục trà lài Milk Foam phô mai', '- 150ml Lục trà lài\n- 40ml Milk foam phô mai đặc biệt\n- Đá viên', '1. Rót lục trà lài đã ủ lạnh ra ly kèm đá.\n2. Phủ lớp milk foam phô mai thơm ngậy lên trên cùng.', '2026-11-01 12:36:04'),
(31, 1, 'Trà sữa Matcha Nhật Bản', '- 5g Bột matcha nguyên chất\n- 30ml Nước ấm\n- 120ml Sữa tươi\n- 20ml Sữa đặc', '1. Hòa tan bột matcha với nước ấm.\n2. Đánh đều matcha với sữa tươi và sữa đặc.\n3. Thêm đá viên và thưởng thức vị matcha đậm đà.', '2026-11-01 12:41:44'),
(32, 1, 'Trà sữa Socola bạc hà', '- 150ml Hồng trà\n- 20g Bột cacao/socola\n- 15ml Syrup bạc hà\n- 20ml Sữa đặc', '1. Hòa tan bột socola và sữa đặc với hồng trà ấm.\n2. Thêm syrup bạc hà để tạo hương vị the mát.\n3. Thêm đá viên và khuấy đều.', '2026-11-01 12:41:44'),
(33, 1, 'Trà sữa Hokkaido đường đen', '- 150ml Hồng trà đặc\n- 25ml Siro caramel Hokkaido\n- 30g Bột béo\n- 20ml Sữa đặc', '1. Ủ hồng trà lấy cốt, hòa cùng bột béo và sữa đặc.\n2. Thêm siro caramel phong cách Hokkaido.\n3. Thêm đá viên và trân châu.', '2026-11-01 12:41:44'),
(34, 1, 'Trà sữa khoai môn tươi', '- 150ml Hồng trà\n- 40g Khoai môn tươi hấp chín nghiền nhuyễn\n- 25ml Sữa tươi\n- 20ml Sữa đặc', '1. Dùng khoai môn nghiền nhuyễn quét quanh thành ly.\n2. Pha hồng trà với sữa tươi và sữa đặc.\n3. Rót trà sữa vào ly khoai môn.', '2026-11-01 12:41:44'),
(35, 5, 'Trà trái cây dâu tây mâm xôi', '- 120ml Lục trà\n- 30ml Syrup dâu tây\n- 20ml Syrup mâm xôi\n- Dâu tây tươi cắt lát', '1. Lắc đều lục trà với syrup dâu và mâm xôi cùng đá viên.\n2. Đổ ra ly và trang trí dâu tây tươi.', '2026-11-01 12:41:44'),
(36, 3, 'Trà xoài kem cheese', '- 120ml Lục trà lài\n- 35ml Syrup xoài\n- 30ml Lớp kem cheese béo ngây', '1. Pha lục trà lài với syrup xoài và đá viên.\n2. Phủ lớp kem cheese sánh mịn lên bề mặt.', '2026-11-01 12:41:44'),
(37, 5, 'Lục trà chanh leo mật ong', '- 120ml Lục trà\n- 30ml Nước cốt chanh leo (có hạt)\n- 25ml Mật ong nguyên chất', '1. Khuấy đều mật ong và nước cốt chanh leo với lục trà.\n2. Thêm đá viên, lắc đều và thưởng thức.', '2026-11-01 12:41:44'),
(38, 1, 'Trà sữa hạt dẻ cười', '- 150ml Hồng trà\n- 25ml Syrup hạt dẻ cười (Pistachio)\n- 30g Bột béo\n- 20ml Sữa đặc', '1. Hòa tan bột béo và sữa đặc với hồng trà ấm.\n2. Thêm syrup hạt dẻ cười tạo mùi thơm bùi đặc trưng.\n3. Thêm đá.', '2026-11-01 12:41:44'),
(39, 1, 'Trà sữa Earl Grey trân châu trắng', '- 150ml Trà Earl Grey (Bá tước)\r\n- 30g Bột kem béo\r\n- 20ml Sữa đặc\r\n- Trân châu trắng giòn', '1. Ủ trà Earl Grey thơm mùi cam bergamot lấy cốt.\r\n2. Pha cùng bột béo và sữa đặc.\r\n3. Thêm trân châu trắng dai giòn.', '2026-11-01 12:41:44');
